def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return min(budget, 18.0)

    prev_bids = []
    aggressive = 0
    desperate_opp = 0
    rich_opp = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= 120:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 100:
                aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 25.0 - float(supply)
    base = 20.0 + scarcity * 3.0

    if float(supply) >= 23.0:
        base -= 10.0
    elif float(supply) <= 17.0:
        base += 18.0

    if hp <= 2:
        base = max(base, 95.0)
    elif hp <= 4:
        base += 18.0

    if no_water >= 2:
        base = max(base, 120.0)
    elif no_water >= 1:
        base += 22.0

    if desperate_opp >= 2:
        base += 12.0

    if aggressive >= 2 and hp > 4 and no_water == 0 and float(supply) >= 20.0:
        base = min(base, 22.0)
    elif highest_prev >= 130.0 and hp > 4 and no_water == 0:
        base = min(base, 28.0)
    elif highest_prev > 0:
        target = avg_prev * 0.72 + 6.0
        if hp <= 4 or no_water >= 1 or float(supply) <= 17.0:
            target = highest_prev + 3.0
        base = max(base, target)

    if rich_opp >= 2 and day <= 3 and hp > 5 and no_water == 0:
        base = min(base, 24.0)

    if day >= 8:
        base += 10.0

    bid = max(0.0, min(float(budget), float(base)))

    if budget < 25:
        bid = min(float(budget), max(bid, float(budget) * 0.9 if (hp <= 3 or no_water >= 1) else float(budget) * 0.45))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQUIREMENT = 13
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    eric_status = opponents_status.get("Eric")

    if not alive_opponents:
        return min(my_budget, MY_DAILY_SALARY * 0.4)

    remaining_days = EPISODE_DAYS - current_day + 1

    bid_multiplier = 0.8 

    if my_hp <= 2: 
        bid_multiplier = 0.98
    elif my_hp <= 4: 
        bid_multiplier = 0.9
    elif remaining_days <= 3 and my_hp < 10: 
        bid_multiplier = 0.95
    elif my_hp >= 8 and current_day > EPISODE_DAYS / 2: 
        bid_multiplier = 0.75

    my_target_bid = MY_DAILY_SALARY * bid_multiplier

    if current_supply <= MY_WATER_REQUIREMENT + 2: 
        my_target_bid = max(my_target_bid, MY_DAILY_SALARY * 0.9)
        if my_hp <= 4: 
            my_target_bid = MY_DAILY_SALARY * 0.99

    eric_prev_bid = 0
    eric_alive = False
    if eric_status and eric_status['alive']:
        eric_alive = True
        if eric_status.get('previous_trace'):
            eric_prev_bid = eric_status['previous_trace'].get('bid', 0)

    if eric_alive and eric_prev_bid > MY_DAILY_SALARY * 0.8: 
        if my_hp <= 3: 
            my_target_bid = max(my_target_bid, eric_prev_bid + 5)
        elif my_hp <= 6: 
            my_target_bid = max(my_target_bid, eric_prev_bid + 1)
        else: 
            my_target_bid = max(my_target_bid, eric_prev_bid * 0.98)

    final_bid = min(my_budget, my_target_bid)

    if my_budget < MY_DAILY_SALARY * 0.7 and my_hp < 10:
        final_bid = min(my_budget, MY_DAILY_SALARY * 0.99)

    if my_hp < 10 and final_bid < MY_DAILY_SALARY * 0.1:
        final_bid = min(my_budget, MY_DAILY_SALARY * 0.1)

    if remaining_days == 1 and my_hp < 10:
        final_bid = min(my_budget, MY_DAILY_SALARY * 1.0)

    return final_bid

